import pathlib,json,base64,hashlib,subprocess
r=pathlib.Path.home()/'hygon-inference-refactor-20261014/incoming'
payload={'Deep-host-clock-launch-spec-r9049.json': '', 'Deep_host_clock_component_r9049.py': '', 'Deep_host_clock_component_r9049_inside.sh': '', 'launch_Deep_host_clock_component_r9049.py': '', 'verify_Deep_host_clock_component_r9049.py': ''}
out={}
for n,b in payload.items():
 p=r/n;data=base64.b64decode(b)
 if p.exists():assert p.read_bytes()==data,n
 else:p.write_bytes(data)
 out[n]=hashlib.sha256(data).hexdigest()
 if n.endswith('.sh'):subprocess.run(['bash','-n',str(p)],check=True)
print(json.dumps({'uploaded':out,'no_job_submitted':True}))
